["```cpp
#include <memory>
#include <mutex>

struct Node {
  std::string name;
  std::shared_ptr<DataSource> dataSource;
  std::shared_ptr<Node> prev;
  std::shared_ptr<Node> next;

  // ... (Other relevant methods and data)
};

class DoublyLinkedList {
 public:
  std::shared_ptr<Node> head;
  std::mutex mutex; 

  void appendOrIntegrateNode(const std::string& name, 
                          std::shared_ptr<DataSource> dataSource) {
    std::lock_guard<std::mutex> lock(mutex); 
    auto current = head;
    while (current != nullptr) {
      if (current->name == name) {
        // Integrate the data source
        current->dataSource = dataSource; // Update existing node's data source
        return;
      }
      current = current->next; 
    }

    // Append new node if it doesn't exist
    auto newNode = std::make_shared<Node>();
    newNode->name = name;
    newNode->dataSource = dataSource;

    if (head == nullptr) {
      head = newNode;
      return;
    }

    auto last = head;
    while (last->next != nullptr) {
      last = last->next; 
    }

    last->next = newNode;
    newNode->prev = last;
  }

