    private readonly HttpClient _httpClient;
    private readonly IMemoryCache _cache;

    public XmlService(HttpClient httpClient, IMemoryCache cache) 
    {
        _httpClient = httpClient;
        _cache = cache;
    }

    public async Task<string> GetXmlDataAsync(string sourceUri)
    {
        if (_cache.TryGetValue(sourceUri, out string cachedXml))
        {
            return cachedXml; 
        }

        try
        {
            HttpResponseMessage response = await _httpClient.GetAsync(sourceUri);
            response.EnsureSuccessStatusCode(); 

            string xmlData = await response.Content.ReadAsStringAsync();

            _cache.Set(sourceUri, xmlData, TimeSpan.FromMinutes(5)); // Cache for 5 minutes

            return xmlData;
        }
        catch (Exception ex)
        {
            // Handle exceptions gracefully with logging and potential user prompts
            Console.WriteLine($"Error retrieving XML from {sourceUri}: {ex.Message}");
