        try {
            // Attempt update up to 3 times with retries and exponential backoff
            for (int i = 0; i < 3; i++) {
                try {
                    ResponseEntity<Resource> response = restTemplate.exchange(apiUrl + "/{id}", HttpMethod.PUT, new HttpEntity<>(updatedResource), Resource.class, id);
                    return response;
                } catch (HttpStatusCodeException e) {
                    // Handle API errors
                    if (i < 2) {
