                    } else {
                        throw e; // Re-throw after 3 attempts
                    }
                } 
            }
        } catch (Exception e) {
            // Handle exceptions and implement fallback mechanism
        }
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(null); 
    }

