    const regex = /([a-zA-Z]+)([ \.,\'\"\?!;:\-]*)/g; 
    const books = ["Genesis", "Exodus", "Leviticus", /* ... other Old Testament books */]; 
    let mentions = {};

    let match;
    while ((match = regex.exec(text))) {
      const bookName = match[1].trim();
      if (books.includes(bookName)) {
        mentions[bookName] = (mentions[bookName] || 0) + 1;
      }
