    }

    public function updatePassword(int $userId, string $newPassword): Response
    {
        if (!preg_match('/^(?=.*[A-Z])(?=.*[a-z])(?=.*\d)(?=.*[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]).{8,}$/', $newPassword)) {
            return new Response('Invalid password format.', 400);
        }

        $retryAttempts = 0;
        $maxRetries = 3;
        while ($retryAttempts < $maxRetries) {
            try {
                $this->dao->updatePassword($userId, $newPassword);
                $backgroundTaskManager->execute(new PasswordUpdatedNotificationTask($userId));
                return new Response('Password updated successfully.', 200);
            } catch (DatabaseException $e) {
                Logger::error("Database error during password update: " . $e->getMessage());
                sleep(pow(2, $retryAttempts));
                $retryAttempts++;
            }
        }

        return new Response('Failed to update password. Please try again later.', 500);
    }
}
