static pthread_mutex_t state_list_mutex;

// Dynamically allocated state list
static State *state_list = NULL;

// Current size of the state list
static int state_list_size = 0;

// Maximum size of the state list before reallocation
static int state_list_capacity = 1024;


// ... (Functions for adding, retrieving, and managing states)

/**
 * Adds a new state to the state list.
 *
 * @param state The new state to be added.
 * @return A status code indicating success or failure.
 */
int add_state(State *state) {
    pthread_mutex_lock(&state_list_mutex);

    if (state_list_size >= state_list_capacity) {
        // Reallocate the state list if necessary
        state_list = realloc(state_list, sizeof(State) * (state_list_capacity * 2));
        if (!state_list) {
            pthread_mutex_unlock(&state_list_mutex);
            return -1; // Memory allocation failed
        }
        state_list_capacity *= 2;
    }

    state_list[state_list_size] = *state;
    state_list_size++;

    pthread_mutex_unlock(&state_list_mutex);

    return 0; // Success
}


