    {
        private static readonly ILogger Logger = LogManager.GetCurrentClassLogger();
        private readonly IRandomNumberGenerator _generator;
        private long _seed;

        public RandomValueGenerator(IRandomNumberGenerator generator, long seed = -1)
        {
            _generator = generator ?? throw new ArgumentNullException(nameof(generator));
            _seed = seed;
        }

        public int GenerateInt(int min, int max)
        {
            if (min > max)
            {
                Logger.Error($"Invalid range: Minimum ({min}) greater than maximum ({max}).");
                throw new ArgumentException("Minimum value must be less than or equal to the maximum value.");
            }

            return _generator.GenerateInt(min, max); 
        }

        public double GenerateDouble(double min, double max)
        {
            if (min > max)
            {
                Logger.Error($"Invalid range: Minimum ({min}) greater than maximum ({max}).");
                throw new ArgumentException("Minimum value must be less than or equal to the maximum value.");
            }

            return _generator.GenerateDouble(min, max); 
