char* processString(const char *input, int sizeLimit, bool caseInsensitive, externalFormatter_t externalFormatter) {
  // Input validation
  if (input == NULL || sizeLimit <= 0 || externalFormatter == NULL) {
    LOG_ERROR("Invalid input parameters"); // Logging using your framework
    return NULL; 
  }

  // Thread-safe operations: Acquire mutex lock
  pthread_mutex_lock(&processStringMutex); 

  if (strlen(input) > sizeLimit) {
    pthread_mutex_unlock(&processStringMutex);
    LOG_WARN("Input string exceeds size limit"); // Logging using your framework
    return NULL;
  }

  // String processing based on caseInsensitive flag
  char *processedString = malloc(sizeLimit + 1); // Allocate memory for processed string
  if (processedString == NULL) {
    pthread_mutex_unlock(&processStringMutex);
    LOG_ERROR("Memory allocation failed"); // Logging using your framework
    return NULL;
  }

  if (!caseInsensitive) {
    strcpy(processedString, input);
    strcat(processedString, "_"); 
  } else {
    // Convert to lowercase and append dash
    for (int i = 0; input[i] != '\0'; i++) {
      processedString[i] = tolower(input[i]); // Assuming a function 'tolower' exists for case conversion
    }
    processedString[strlen(input)] = '-'; 
  }

  // Invoke externalFormatter for API compliance and formatting
  externalFormatter(input, processedString, sizeLimit);

  pthread_mutex_unlock(&processStringMutex); // Release mutex lock after processing
  LOG_DEBUG("Processed string: %s", processedString); // Logging using your framework
  return processedString; 
}



