  FILE *fp = fopen("input.csv", "r");
  if (!fp) {
    perror("Error opening input file");
    return -1;
  }

  while (fgets(line, sizeof(line), fp)) {
    processLine(line);
  }

  fclose(fp);
  return 0;
}


