public class Base64TripleDESDecrypter
{
    private readonly string _loggingServiceUrl; 

    public Base64TripleDESDecrypter(string loggingServiceUrl)
    {
        _loggingServiceUrl = loggingServiceUrl;
    }

    public async Task<int> DecryptAndFindLargestIntegerAsync(string encryptedMessage, byte[] key, byte[] iv)
    {
        try 
        {
            // Base64 decoding
            byte[] decodedBytes = Convert.FromBase64String(encryptedMessage);

            // Triple DES decryption
            using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
            {
                tdes.Key = key;
                tdes.IV = iv;
                ICryptoTransform decryptor = tdes.CreateDecryptor();
                byte[] decryptedBytes = decryptor.TransformFinalBlock(decodedBytes, 0, decodedBytes.Length);

                // Parse into integers and find the largest
                string decryptedString = Encoding.UTF8.GetString(decryptedBytes);
                int[] integers = Array.ConvertAll(decryptedString.Split(','), int.Parse);
                return FindLargestInteger(integers);
            }
        }
        catch (Exception ex)
        {
            // Log the error to the external service and handle gracefully
            await LogErrorAsync(_loggingServiceUrl, "Decryption Error", ex);
            throw; 
        }
    }

    private int FindLargestInteger(int[] integers)
    {
        if (integers.Length == 0)
        {
            return default; // Handle empty array
        }

        int largest = integers[0];
        foreach (int integer in integers)
        {
            if (integer > largest)
            {
                largest = integer;
            }
        }
        return largest;
    }

    // ... (Asynchronous Logging Method - Implement using a suitable library)
}



