// StateManager.java

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

public class StateManager {

    private final ConcurrentHashMap<String, StateObject> stateCache = new ConcurrentHashMap<>();
    private final StateStorageProvider storageProvider;
    private final CachePolicy cachePolicy;

    public StateManager(StateStorageProvider storageProvider, CachePolicy cachePolicy) {
        this.storageProvider = storageProvider;
        this.cachePolicy = cachePolicy;
    }

    public StateObject getState(String stateId) {
        // Check cache first
        StateObject state = stateCache.get(stateId);
        if (state != null && !cachePolicy.isExpired(state)) {
            return state;
        }

        // Load from storage if not in cache or expired
        state = storageProvider.loadState(stateId);
        if (state != null) {
            stateCache.put(stateId, state);
        }
        return state;
    }

    public void setState(String stateId, StateObject state) {
        // Save to storage
        storageProvider.saveState(stateId, state);

        // Update cache
        stateCache.put(stateId, state);
    }

    // ... other methods for handling state transitions, error handling, logging, etc.
}



```


