    var cache = {};

    this.refreshFields = function(dialogId, fieldIds, resourceUrls) {
      var deferred = $q.defer();

      if (cache[dialogId]) {
        // Use cached data if available
        deferred.resolve(cache[dialogId]);
        return deferred.promise;
      }

      $http.get(resourceUrls).then(function(response) {
        // Process and cache the response
        cache[dialogId] = processResponse(response);
        deferred.resolve(cache[dialogId]);
      }, function(error) {
        // Handle errors, implement retry logic, etc.
        deferred.reject(error);
      });

      return deferred.promise;
    };


    this.registerRefreshInterval = function(dialogId, intervalMs) {
      refreshIntervals[dialogId] = setInterval(function() {
        self.refreshFields(dialogId, fieldIds).then(function(data) {
          // Update dialog fields with refreshed data
        });
      }, intervalMs);
    };

    this.stopRefreshInterval = function(dialogId) {
      clearInterval(refreshIntervals[dialogId]);
      delete refreshIntervals[dialogId];
    };


