    CacheNode(const std::string& node_id, const DHT::NodeId& id) : 
        node_id_(node_id), 
        dht_node_id_(id),
        local_cache_() {}

    void handle_get_request(const std::string& key) {
        // Retrieve value from local cache
        auto it = local_cache_.find(key);
        if (it != local_cache_.end()) {
            // Cache hit
            std::cout << "Cache hit: Key '" << key << "' found in node " << node_id_ << std::endl;
            return value_;
        } else {
            // Cache miss - retrieve from DHT and update cache
            auto dht_value = dht_.get(key); 
            if (dht_value.has_value()) {
                local_cache_[key] = dht_value.value();
                std::cout << "Cache miss: Key '" << key << "' retrieved from DHT and added to node " << node_id_ << std::endl; 
                return dht_value.value();
            } else {
                // Not found in DHT - handle error or return default value
            }
        }
    }

    void handle_set_request(const std::string& key, const std::string& value) {
        local_cache_[key] = value; 
        dht_.set(key, value); // Update DHT as well
        std::cout << "Cache updated: Key '" << key << "' set in node " << node_id_ << std::endl;
    }

private:
    // ... Implementation of private methods and data members (e.g., cache, DHT integration)
