public class FilterAndDeserializeTransaction {

    private final TransactionValidator validator;
    private final Cache<String, Boolean> validationCache; // Memory constraint: 2GB

    public FilterAndDeserializeTransaction(TransactionValidator validator) {
        this.validator = validator;
        validationCache = new CustomCache<>(2 * 1024 * 1024 * 1024L); // 2GB cache
    }

    public Transaction processTransaction(byte[] transactionData) {
        try {
            Transaction transaction = (Transaction) SerializationUtil.deserialize(transactionData);
            if (validationCache.containsKey(transaction.getId())) {
                return validationCache.get(transaction.getId()) ? transaction : null; 
            }

            boolean isValid = validator.validateTransaction(transaction, 50L); // 50ms timeout
            validationCache.put(transaction.getId(), isValid); 
            if (isValid) {
                return transaction;
            } else {
                LOGGER.error("Invalid transaction: {} - {}", transaction.getId(), transaction.toString());
                return null;
            }

        } catch (SerializationException e) {
            LOGGER.error("Deserialization error: {} - {}", transactionData, e.getMessage());
            return null;
        } 
    }

}



// ... (Code for REST API endpoints, resource update/deletion functions using HTTP PUT and DELETE methods) 


