public class SecureCommandExecutor {

    private static final Logger logger = Logger.getLogger(SecureCommandExecutor.class.getName());

    public static void executeCommand(String command, String workingDirectory) throws IOException {
        ProcessBuilder processBuilder = new ProcessBuilder("bash", "-c", command);
        processBuilder.directory(new File(workingDirectory));

        Process process = processBuilder.start();

        // Read output and error streams
        new Thread(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    logger.info("Output: " + line);
                }
            } catch (IOException e) {
                logger.error("Error reading output stream:", e);
            }
        }).start();

        new Thread(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    logger.warn("Error: " + line);
                }
            } catch (IOException e) {
                logger.error("Error reading error stream:", e);
            }
        }).start();

        // Wait for command to complete
        int exitCode = process.waitFor();

        logger.info("Command execution completed with exit code: " + exitCode);
    }
}
``` 



