    public DataProcessingPipeline(string connectionString, string queueName)
    {
        _connectionString = connectionString;
        _connectionFactory = new ServiceBusConnectionFactory(connectionString);
        _queueClient = _connectionFactory.CreateQueueClient(queueName); // Initialize message broker client
    }

    public async Task ProcessDataAsync()
    {
        while (true)
        {
            var message = await _queueClient.ReceiveAsync(); 

            if (message != null)
            {
                try
                {
                    // Parse and process incoming data from the message
                    var data = JsonConvert.DeserializeObject<Data>(message.Body);

                    // Perform database operations using Dapper
                    using (var connection = new SqlConnection(_connectionString))
                    {
                        await connection.ExecuteAsync("INSERT INTO MyTable (Data) VALUES (@Data)", data); 
                    }

                    // Call external APIs and handle responses with retries and circuit breakers
                    var apiResponse = await _httpClient.GetAsync($"https://api.example.com/endpoint/{data.Id}");

                    // ... Process API response, implement retry mechanisms, circuit breaker pattern
                }
                catch (Exception ex)
                {
                    // Log exceptions and implement error handling strategies
                }
                finally 
                {
                    await _queueClient.CompleteAsync(message); // Indicate successful processing
                }
            }
        }
    }
}

