// Package declaration

import java.util.*;
import com.fasterxml.jackson.databind.*; // For JSON handling
import org.springframework.boot.SpringApplication; 
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.cloud.netflix.eureka.EnableEurekaClient; // For service discovery
import org.springframework.data.redis.connection.RedisStandaloneConfiguration;
import org.springframework.data.redis.connection.lettuce.LettuceConnectionFactory;
import org.springframework.data.redis.core.RedisTemplate;

@SpringBootApplication
@EnableEurekaClient
@EnableCaching 
public class SessionManagementService {

    public static void main(String[] args) {
        SpringApplication.run(SessionManagementService.class, args);
    }

    // Bean for Redis connection factory
    @Bean
    LettuceConnectionFactory redisConnectionFactory() {
        RedisStandaloneConfiguration configuration = new RedisStandaloneConfiguration("redis-host", 6379);
        return new LettuceConnectionFactory(configuration);
    }

    // Bean for Redis template
    @Bean
    RedisTemplate<String, Object> redisTemplate() {
        RedisTemplate<String, Object> template = new RedisTemplate<>();
        template.setConnectionFactory(redisConnectionFactory());
        return template;
    } 
}


```

