// Function to load and validate Resource Bundle from file
int load_resource_bundle(const char* filename, ResourceBundle* bundle) {
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) { 
        fprintf(stderr, "Error opening file: %s\n", filename);
        return -1; // Error opening file
    }

    fseek(fp, 0L, SEEK_END);
    bundle->size = ftell(fp);
    rewind(fp);
    bundle->data = malloc(bundle->size + 1); // Allocate memory for data
    if (bundle->data == NULL) {
        fclose(fp);
        fprintf(stderr, "Memory allocation failed!\n");
        return -2; // Memory allocation error
    }

    fread(bundle->data, bundle->size, 1, fp);
    fclose(fp);

    // ... (Read checksum from file, validate against calculated checksum)

    return 0; // Success
}



