typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
} CRCArray;

// Function to dynamically allocate memory for the array
CRCArray* createCRCArray(size_t initialCapacity) {
    CRCArray* array = (CRCArray*)malloc(sizeof(CRCArray));
    array->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initialCapacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->size = 0;
    array->capacity = initialCapacity;
    return array;
}

// Function to add a new CRC indication to the array
void addCRCIndication(CRCArray* array, RX_UE_INFORMATION_TAG rx_ue_info, uint32_t rnti, uint8_t crcflag) {
    if (array->size == array->capacity) {
        // Resize the array if it's full
        array->capacity *= 2;
        array->data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->data, array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Add the new CRC indication to the array
    array->data[array->size].RX_UE_INFORMATION_TAG = rx_ue_info;
    array->data[array->size].RNTI = rnti;
    array->data[array->size].CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag; 
    array->size++;
}

// Example usage:
