#include <sys/time.h>
#include <time.h>

std::string modifyFilename(const std::string& filename) {
  struct timeval tv;
  gettimeofday(&tv, NULL);
  char timestamp[20]; 
  strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", localtime(&tv.tv_sec));
  int uniqueId = rand(); // Generate a simple unique ID

  std::string newFilename;
  sprintf(newFilename.data(), "%s_%s_%d.%s", filename.c_str(), timestamp, uniqueId, filename.substr(filename.find('.') + 1).c_str());

  return newFilename;
}

int main() {
  std::string filename = "example.txt";
  std::string modifiedFilename = modifyFilename(filename);
  std::cout << "Modified filename: " << modifiedFilename << std::endl;
  return 0;
}
