import org.apache.kafka.clients.consumer.*;
import org.apache.http.client.methods.*;
import com.google.gson.Gson;

public class DataTransformationPlatform {

    private KafkaConsumer<String, String> kafkaConsumer;
    private EncodingService encodingService;
    private CacheManager cacheManager;
    private ConfigurationManager configManager;

    public DataTransformationPlatform(ConfigurationManager configManager) {
        this.configManager = configManager;
        this.encodingService = new EncodingService(configManager); 
        this.kafkaConsumer = new KafkaConsumer<>(configManager.getKafkaConfig());
        this.cacheManager = new CacheManager(configManager); 
    }

    public void start() {
        // Initialize kafka consumer with topic configurations
        kafkaConsumer.subscribe(configManager.getKafkaTopics());
        new Thread(() -> {
            while (true) {
                ConsumerRecords<String, String> records = kafkaConsumer.poll(Duration.ofMillis(100));
                for (ConsumerRecord<String, String> record : records) {
                    processMessage(record);
                }
            }
        }).start(); 

