using System;
using System.IO;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using Newtonsoft.Json;

namespace ResourceBundleService
{
    public class ResourceBundleService : IResourceBundleService
    {
        private readonly HttpClient _httpClient;
        private readonly string _apiBaseUrl;
        private readonly IMemoryCache _cache;
        private readonly int _maxRetries = 3;
        private readonly TimeSpan _retryInterval = TimeSpan.FromSeconds(1);

        public ResourceBundleService(HttpClient httpClient, string apiBaseUrl, IMemoryCache cache)
        {
            _httpClient = httpClient;
            _apiBaseUrl = apiBaseUrl;
            _cache = cache;
        }

        public async Task<string> GetResourceBundleAsync(string resourceId, CancellationToken cancellationToken)
        {
            if (_cache.TryGetValue(resourceId, out string cachedValue))
            {
                return cachedValue;
            }

            try
            {
                var response = await _httpClient.GetAsync($"{_apiBaseUrl}/{resourceId}", cancellationToken);
                response.EnsureSuccessStatusCode();

                using (var contentStream = await response.Content.ReadAsStreamAsync(cancellationToken))
                {
                    // Process and serialize the resource bundle data
                    // ...
                    string processedData = "Processed Data"; 

                    _cache.Set(resourceId, processedData, TimeSpan.FromMinutes(10)); // Cache for 10 minutes
                    return processedData;
                }
            }
            catch (HttpRequestException ex)
            {
                // Handle API errors gracefully, retry if transient, switch to backup provider otherwise
                if (IsTransientError(ex))
                {
                    await RetryAsync(resourceId, cancellationToken);
                }
                else
                {
                    // Log the error and potentially notify administrators
                }
            }

            return null;
        }

        private async Task RetryAsync(string resourceId, CancellationToken cancellationToken)
        {
            int retryCount = 0;
            while (retryCount < _maxRetries)
            {
                await Task.Delay(_retryInterval, cancellationToken);
                try
                {
                    // Attempt to fetch the resource bundle again
                    await GetResourceBundleAsync(resourceId, cancellationToken);
                    return; // Successful retry
                }
                catch (Exception ex)
                {
                    // Log the error and increment retry count
                    retryCount++;
                }
            }

            // Give up after retries
        }

        private bool IsTransientError(HttpRequestException ex)
        {
            // Check for transient errors like connection timeouts or server unavailability
            return ex.StatusCode == System.Net.HttpStatusCode.RequestTimeout ||
                   ex.StatusCode == System.Net.HttpStatusCode.ServiceUnavailable;
        }

    }
}
