class Task:
    def __init__(self, name, dependencies, execution_function):
        self.name = name
        self.dependencies = dependencies
        self.execution_function = execution_function

def runPipelineTasks(pipeline_config):
    task_registry = {}
    for task_data in pipeline_config:
        task_registry[task_data['name']] = Task(**task_data)

    #  Dynamic Scheduling Logic (Simplified)
    scheduled_tasks = []
    for task_name in pipeline_config:
        if not any(t.name == task_name for t in scheduled_tasks):
            dependencies_met = all(dependency in scheduled_tasks for dependency in task_registry[task_name].dependencies)
            if dependencies_met:
                scheduled_tasks.append(task_registry[task_name])

    # Task Execution (Simplified)
    for task in scheduled_tasks:
        try:
            task.execution_function() 
        except Exception as e:
            print(f"Error executing {task.name}: {e}")

