angular.module('myApp', [])
  .service('employeeDialogService', function($http, $q) {

    // Cache for employee dialog data 
    var cache = {};

    this.refreshDialog = function(dialogId) {
      var deferred = $q.defer();
      if (cache[dialogId]) {
        deferred.resolve(cache[dialogId]);
      } else {
        // Fetch data from API based on dialogId
        $http({method: 'GET', url: '/api/employee/' + dialogId}).then(function(response) {
          cache[dialogId] = response.data;
          deferred.resolve(response.data);
        }, function(error) {
          // Handle API errors and fallback strategies
