// app.js
function refreshDialogFields(resource_id, url) {
  const fieldNames = ['fieldName1', 'fieldName2', 'fieldName3']; // Array of fields to refresh

  for (let i = 0; i < dialogFields.length; i++) {
    const fieldName = dialogFields[i].name;

    if (fieldNames.includes(fieldName)) {
      // Send message to parent window
      window.parent.postMessage({
        resourceId: resource_id,
        fieldName: fieldName,
        action: 'refresh'
      }, '*');

      // Update dialog field if the response is successful
      window.addEventListener('message', function(event) {
        if (event.data && event.data.success && event.data.fieldName === fieldName) {
          dialogFields[i].value = event.data.result;
        }
      });
    }
  }
}
