use tokio::runtime::Builder;
use futures::{StreamExt};

// ... (Implementation for other functionalities)

async fn compile_projects(projects: Vec<Project>) -> Result<(), Error> {
    let runtime = Builder::new_current_thread()
        .worker_threads(num_cpus::get()) // Use all available cores
        .enable_all().build()?;

    let mut work_queue = tokio::sync::mpsc::UnboundedSender::<Project>::new();

    // Start worker pool
    for _ in 0..num_workers {
        runtime.spawn(async move {
            loop {
                let project = work_queue.recv().await.unwrap();
                compile_project(&project).await;
            }
        });
    }

    // Enqueue projects for compilation
    for project in projects {
        work_queue.send(project).await.unwrap();
    }

    runtime.shutdown().await?;

    Ok(())
}


