    std::mutex queueMutex;
public:
    VideoProcessor(MediaPipeline* pipeline) : pipeline(pipeline) {}

    void addVideo(const std::string& filename) {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            videoQueue.push(filename);
        }
    }

    void process() {
        while (true) { 
            std::string filename;
            {
                std::lock_guard<std::mutex> lock(queueMutex);
                if (!videoQueue.empty()) {
                    filename = videoQueue.front();
                    videoQueue.pop();
                } else {
                    // Handle empty queue (e.g., sleep)
                }
            }

            if (!filename.empty()) {
                pipeline->uploadVideo(filename); // Upload to pipeline
                pipeline->processVideo(filename); // Process video
            } 
        }
    }
};


int main() {
    MediaPipeline* pipeline = new MediaPipeline();
    VideoProcessor processor(pipeline);

    // Start processing thread
    std::thread processingThread(&VideoProcessor::process, &processor);

    // Add videos to the queue
    processor.addVideo("video1.mp4"); 
    processor.addVideo("video2.mkv");

    // Keep main thread alive (adjust for your needs)
    processingThread.join();
    delete pipeline;
}
