#include <mutex>
#include <queue>
#include <condition_variable>

class VideoStreamProcessor {
 public:
  VideoStreamProcessor() : 
    streamQueue(), streamCondition(streamQueue), workerThreads() {}

  void StartWorkers(int numThreads) {
    for (int i = 0; i < numThreads; ++i) {
      workerThreads.emplace_back([this]() { ProcessStreams(); });
    }
  }

  void EnqueueVideoStream(const std::string& streamUrl) {
    std::lock_guard<std::mutex> lock(streamMutex);
    streamQueue.push(streamUrl);
    streamCondition.notify_one(); 
  }

 private:
  void ProcessStreams() {
    while (true) {
      std::unique_lock<std::mutex> lock(streamMutex);
      streamCondition.wait(lock, [this] { return !streamQueue.empty(); });
      const std::string& streamUrl = streamQueue.front();
      streamQueue.pop();
      lock.unlock();

      // Simulate processing video stream 
      std::cout << "Processing stream: " << streamUrl << std::endl; 

      // ... Logic to process, optimize and transcode the stream ...

    }
  }

  std::queue<std::string> streamQueue; 
  std::mutex streamMutex;
  std::condition_variable streamCondition;
  std::vector<std::thread> workerThreads;
};


int main() {
  VideoStreamProcessor processor;
  processor.StartWorkers(4); // Start 4 processing threads

  // Enqueue video streams
  processor.EnqueueVideoStream("https://example.com/stream1.mp4");
  processor.EnqueueVideoStream("https://example.com/stream2.avi");

  return 0;
}
```


