pthread_mutex_t request_queue_mutex;
pthread_cond_t request_queue_cond;
QueryRequest *request_queue[1024];
int request_queue_head = 0;
int request_queue_tail = 0;

void *dns_worker(void *arg) {
  while (1) {
    pthread_mutex_lock(&request_queue_mutex);
    while (request_queue_head == request_queue_tail) {
      pthread_cond_wait(&request_queue_cond, &request_queue_mutex);
    }
    QueryRequest *request = request_queue[request_queue_tail];
    request_queue_tail = (request_queue_tail + 1) % 1024;

    pthread_mutex_unlock(&request_queue_mutex);

    // ... (Perform DNS resolution using external API)

    // ... (Send response to client)
  }
  return NULL;
}

void handle_client_request(struct sockaddr_in *client_addr, char *hostname) {
  pthread_mutex_lock(&request_queue_mutex);
  request_queue[request_queue_head].hostname = hostname;
  request_queue[request_queue_head].client_addr = *client_addr;
  request_queue_head = (request_queue_head + 1) % 1024;
  pthread_cond_signal(&request_queue_cond);
  pthread_mutex_unlock(&request_queue_mutex);
}

int main() {
  // ... (Socket setup and bind)

  // Create worker threads
