@RestController
public class UserPageGenerator {

    private final RestTemplate restTemplate; // For making requests to the external template API
    private final Semaphore semaphore = new Semaphore(10); // Adjust concurrency level as needed
    private final Bucket apiRateLimitBucket; 

    // ... Constructor, init methods for dependencies

    @PostMapping("/generate")
    public UserPage generatePage(@RequestBody UserRequest request) throws IOException {
        UserPage page = new UserPage();
        try {
            semaphore.acquire(); // Acquire semaphore before critical section
            // Fetch template from external API using RestTemplate (handle errors, retry, backoff)
            String htmlTemplate = restTemplate.getForObject("https://api.example.com/template/{userId}", String.class, request.getUserId());

            // Update specified sections of the template based on user data
            // ... Logic to update HTML content

            // Generate MD5 hash of the updated HTML content using MessageDigest
            String md5Hash = generateMD5Hash(htmlTemplate);

            page.setContent(htmlTemplate);
            page.setMd5Hash(md5Hash); 
        } finally {
            semaphore.release(); // Release semaphore after critical section
        }
        return page;
    }

    private String generateMD5Hash(String content) throws NoSuchAlgorithmException, UnsupportedEncodingException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] hashBytes = md.digest(content.getBytes("UTF-8"));
        return bytesToHex(hashBytes);
    }

