            var content = JsonConvert.SerializeObject(requestBody);
            var response = await client.PostAsync("http://microservice-host:port/generate", new StringContent(content, System.Text.Encoding.UTF8, "application/json"));

            if (response.IsSuccessStatusCode)
            {
