    }

    public DataTableReader ProcessData(byte[] data)
    {
        // 1. Establish Database Connection
        using (var connection = new SqlConnection(_connectionString))
        {
            connection.Open();

            // 2. Create SQL Command & Parameters
            string sqlQuery = "INSERT INTO YourTable (YourColumn) VALUES (@Data)";
            using (var command = new SqlCommand(sqlQuery, connection))
            {
                command.Parameters.AddWithValue("@Data", data);

                // 3. Execute Query
                command.ExecuteNonQuery(); // Assuming an insert operation for demonstration

                // 4. Retrieve Data (Example: SELECT query)
                string selectQuery = "SELECT * FROM YourTable";
                using (var reader = new SqlCommand(selectQuery, connection).ExecuteReader())
                {
                    return reader; // Return DataTableReader object
                }
            }
        }
    }
}


```

