using System;
using System.Security.Cryptography;

public static class EncryptionHelper
{
    public static string DecryptBase64EncryptedMessage(string base64EncodedMessage, string key, byte[] iv)
    {
        byte[] encryptedBytes = Convert.FromBase64String(base64EncodedMessage);

        using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
        {
            tdes.Key = ASCIIEncoding.ASCII.GetBytes(key);
            tdes.IV = iv;

            using (MemoryStream ms = new MemoryStream(encryptedBytes))
            {
                using (CryptoStream cs = new CryptoStream(ms, tdes.CreateDecryptor(), CryptoStreamMode.Read))
                {
                    using (StreamReader sr = new StreamReader(cs))
                    {
                        return sr.ReadToEnd();
                    }
                }
            }
        }
    }
}
