void threadSafeInsertAfterFirst(std::forward_list<std::string>& list, const std::string& firstString, const std::string& secondString) {
    auto it = std::find(list.begin(), list.end(), firstString); 
    if (it != list.end()) {
        // Found the string, insert after it
        list.insert(it, secondString);  
    } else {
        // Not found, append to the end
        list.push_back(secondString);
    }
}



