    private final AuthenticationService authService;
    private final MonitoringSystem monitoringSystem;

    public DistributedCommandService(int numThreads, String apiEndpoints) {
        // Initialize ThreadPoolExecutor for asynchronous command execution
        this.commandExecutor = new ThreadPoolExecutor(
                numThreads, 
                numThreads,
                60L, TimeUnit.SECONDS,
                new LinkedBlockingQueue<>()
        );

        // Initialize ConnectionPool for managing connections to API endpoints
        this.connectionPool = new ConnectionPool(apiEndpoints);

        // Initialize AuthenticationService for command validation
