        // Initialize MonitoringSystem for tracking command execution and errors
        this.monitoringSystem = new MonitoringSystem(); // Implement your monitoring logic
    }

    public void executeCommand(String userId, String command) {
        if (authService.validateCommand(userId, command)) {
            commandExecutor.submit(() -> {
                try (Connection connection = connectionPool.getConnection()) {
                    // Execute the command asynchronously through the connection
                    monitoringSystem.logCommandExecutionStart(userId, command); 

