// Video file processing task
struct VideoProcessingTask {
    std::string filePath;
};

// Global queue for video processing tasks
std::queue<VideoProcessingTask> taskQueue;
std::mutex queueMutex;
std::condition_variable queueCV;

// Worker threads to process video files
std::vector<std::thread> workers;
const int numWorkers = 4; // Adjust based on system resources

void workerThread() {
    while (true) {
        std::unique_lock<std::mutex> lock(queueMutex);
        queueCV.wait(lock, [] { return !taskQueue.empty(); });

        VideoProcessingTask task = taskQueue.front();
        taskQueue.pop();
        lock.unlock();

        // Process video file using MediaProcessingAPI
        MediaProcessingAPI api;
        bool success = api.convertToMP4(task.filePath).get(); 

        if (success) {
            std::cout << "Processed: " << task.filePath << std::endl;
        } else {
            std::cerr << "Error processing: " << task.filePath << std::endl;
        }
    }
}

int main() {
    // Initialize worker threads
    for (int i = 0; i < numWorkers; ++i) {
        workers.emplace_back(workerThread);
    }

    // Simulate uploading video files
    std::vector<std::string> videoFiles = {"file1.mp4", "file2.avi", "file3.mov"};
    for (const auto& file : videoFiles) {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            taskQueue.push({file});
        }
        queueCV.notify_one(); 
    }

    // Keep main thread alive until workers finish processing
    for (auto& worker : workers) {
        worker.join();
    }

    return 0;
}
