class BaseJSON:
    def __init__(self, **kwargs):
        for key, value in kwargs.items():
            setattr(self, key, value)

    def __str__(self):
        return str(self.__dict__)

class JSONRegistry:
    def __init__(self):
        self._registry = weakref.WeakValueDictionary()

    def register(self, json_type, factory):
        self._registry[json_type] = factory

    def unregister(self, json_type):
        del self._registry[json_type]

    def get_factory(self, json_type):
        return self._registry.get(json_type)

# ... (Remaining code for API integration, threading, caching, etc.) 


