// C++ Semaphore Implementation 
#include <mutex>
#include <condition_variable>

class Semaphore {
private:
    int _count;
    std::mutex _mutex;
    std::condition_variable _cv;

public:
    Semaphore(int count) : _count(count) {}

    void wait() {
        std::unique_lock<std::mutex> lock(_mutex);
        while (_count <= 0) {
            _cv.wait(lock); // Wait until a resource becomes available
        }
        --_count;
    }

    void notify() {
        std::unique_lock<std::mutex> lock(_mutex);
        ++_count;
        _cv.notify_one(); // Notify a waiting thread
    }

    // ... (Additional methods for monitoring, statistics)
};
```

