static std::map<std::string, RandomNumberGenerator*> generators;
static std::mutex generators_mutex;

void initializeGenerator(const std::string& name, std::uint32_t seed) {
  std::lock_guard<std::mutex> lock(generators_mutex);
  generators[name] = new RandomNumberGenerator(seed);
}

RandomNumberGenerator* getGenerator(const std::string& name) {
