class DisjointPairAnalyzer {
  constructor(storageProviderFactory, unionFind) {
    this.storageProvider = storageProviderFactory.create(); // Inject Storage Provider 
    this.unionFind = unionFind; // Inject Union-Find Data Structure
  }

  async analyze(fileUrl) {
    try {
      const fileContent = await this.storageProvider.readFile(fileUrl);
      const pairs = this.unionFind.analyze(fileContent);
      return { count: pairs, metrics: this.getMetrics() }; 
