async function copyBytesFromStream(dataStream, byteCount) {
  try {
    let bytesCopied = 0;
    while (bytesCopied < byteCount) {
      const chunk = await dataStream.read(Math.min(byteCount - bytesCopied, 4096)); // Read in chunks for efficiency
      if (chunk.length === 0) {
        throw new Error('End of stream reached before requested byte count');
      }
      bytesCopied += chunk.length;
      // Process or write the chunk here as needed
