public static XElement GetFirstXmlElementByName(string xml, string elementName)
{
    var doc = XDocument.Parse(xml);
    var element = doc.XPathSelectElement(string.Format("./{0}", elementName));

    if (element == null)
    {
        throw new InvalidOperationException($"No element named '{elementName}' found in XML.");
    }

    // Check if more than one element is found
    var count = doc.XPathSelectElements(string.Format("./{0}", elementName)).Count();
    if (count > 1)
    {
        throw new InvalidOperationException($"Multiple elements named '{elementName}' found in XML.");
    }

    return element;
}
