const oldTestamentBooks = /Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi/i;

function extractBibleBooks(text) {
  const bookCounts = {};
  const words = text.replace(/[^a-zA-Z\s]/g, "").toLowerCase().split(/\s+/);

  for (const word of words) {
    if (oldTestamentBooks.test(word)) {
      bookCounts[word] = (bookCounts[word] || 0) + 1;
    }
  }

  return bookCounts;
}
