import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.cloud.client.discovery.EnableDiscoveryClient;
import org.springframework.context.annotation.Bean;
import org.springframework.data.redis.connection.RedisStandaloneConfiguration;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.data.redis.serializer.GenericJackson2JsonRedisSerializer;

@SpringBootApplication
@EnableDiscoveryClient 
@EnableCaching
public class SessionManagementService {

    public static void main(String[] args) {
        SpringApplication.run(SessionManagementService.class, args);
    }

    // Redis configuration for session data storage
    @Bean
    public RedisTemplate<String, Object> redisTemplate() {
        RedisStandaloneConfiguration configuration = new RedisStandaloneConfiguration();
        configuration.setHostName("redis-host"); // Replace with your Redis host
        configuration.setPort(6379); 

        RedisTemplate<String, Object> template = new RedisTemplate<>();
        template.setConnectionFactory(new RedisConnectionFactory(configuration));
        template.setDefaultSerializer(new GenericJackson2JsonRedisSerializer());
        return template;
    }
}



```




