['```javascript
const asyncReduce = (numbers, initialValue, callback) => {
  let accumulator = initialValue;

  return new Promise((resolve, reject) => {
    numbers.reduce((prev, current) => {
      return callback(accumulator, current)
        .then((result) => {
          accumulator = result;
          return Promise.resolve(accumulator);
        })
        .catch(reject);
    }, Promise.resolve());

    Promise.resolve(accumulator).then(resolve).catch(reject);
  });
};

// Example usage:
asyncReduce([1, 2, 3], 0, (acc, num) => {
  return new Promise((resolve) => setTimeout(() => resolve(acc + num), 10));
})
  .then((result) => console.log("Result:", result)) // Expected Output: Result: 6
  .catch((error) => console.error("Error:", error));
