// UEDataProcessor.java

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class UEDataProcessor {

    private final DataIngestor dataIngestor;
    private final HashGenerator hashGenerator;

    public UEDataProcessor(DataIngestor dataIngestor, HashGenerator hashGenerator) {
        this.dataIngestor = dataIngestor;
        this.hashGenerator = hashGenerator;
    }

    public void processUEData(UEData ueData) {
        String hashedData = hashGenerator.generateHash(ueData.getData());

        // Process and store the hashed data 
        dataIngestor.ingestData(ueData, hashedData);
    }

    private static class HashGenerator {
        public String generateHash(String data) {
            try {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] hashBytes = md.digest(data.getBytes());
                return convertToHex(hashBytes);
            } catch (NoSuchAlgorithmException e) {
                // Handle exception appropriately
            }
            return null; 
        }

        private String convertToHex(byte[] data) {
            StringBuilder sb = new StringBuilder();
            for (byte b : data) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        }
    }
}


```



