// This is a code skeleton and requires significant expansion for a fully functional microservice.

import io.jsonwebtoken.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

@RestController
@RequestMapping("/hash")
public class HashMicroservice {

    @Autowired
    private JwtDecoder jwtDecoder; 

    @Autowired
    private ExternalAuthenticationService authenticationService;

    @Autowired
    private DistributedDatabase db;

    @PostMapping
    public ResponseEntity<Map<String, Object>> processHashes(@RequestBody List<HashRequest> requests) {
        Map<String, Object> response = new HashMap<>(); 

        for (HashRequest request : requests) {
            try {
                // Validate JWT token for user authentication
                Claims claims = jwtDecoder.decode(request.getToken());
                String userId = claims.getSubject(); 
                String tenantId = claims.get("tenantId", String.class);

                // Authenticate user with external service
                boolean authenticated = authenticationService.authenticate(userId, tenantId);
                if (!authenticated) {
                    response.put("error", "Authentication failed");
                    return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(response);
                } 

                String inputString = request.getString();
                // Calculate SHA-256 hash
                byte[] hashedBytes = calculateSHA256Hash(inputString);
                String hash = bytesToHex(hashedBytes);  

                // Store hash in distributed database
                db.saveHash(userId, tenantId, inputString, hash); 

                response.put("user_id", userId);
                response.put("tenant_id", tenantId);
                response.put("hash", hash); 

            } catch (Exception e) {
                // Log error and handle exception appropriately
                response.put("error", "Hash calculation failed");
                return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(response);
            }
        }
        return ResponseEntity.ok(response);
    } 

    private byte[] calculateSHA256Hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            return md.digest(input.getBytes());
        } catch (NoSuchAlgorithmException e) {
            // Handle exception appropriately
            throw new RuntimeException(e);
        } 
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b)); 
        }
        return sb.toString();
    }   
}
```

