    public static int countDisjointPairs(int[] arr) {
        UnionFind uf = new UnionFind(arr.length);
        long startTime = System.currentTimeMillis();
        for (int i = 0; i < arr.length; i++) {
            for (int j = i + 1; j < arr.length; j++) {
                if (uf.find(i) != uf.find(j)) {
                    // Pair is disjoint, union the sets
                    uf.union(i, j);
                }
            }
        }
        long endTime = System.currentTimeMillis();
        System.out.println("Time taken: " + (endTime - startTime) + "ms"); 
        return uf.getCount(); 
    }

    // ... (Rest of the UEDataProcessor class implementation)

}

class UnionFind {
    private int[] parent;
    private int[] rank;
    private int count;

    public UnionFind(int n) {
        parent = new int[n];
        rank = new int[n];
        count = n;
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

