char* appendSlash(const char *str, int sizeLimit) {
  if (strlen(str) <= sizeLimit) {
    char *result = malloc(sizeLimit + 2); // Allocate memory for the result string plus slash and null terminator
    strcpy(result, str); 
    strcat(result, "/");
    return result;
  } else {
    return NULL; // Return NULL if the string exceeds the size limit
  }
}

int main() {
  // Example usage:
  char *inputString = "This is a test string";
  int sizeLimit = 20; 

  char* modifiedString = appendSlash(inputString, sizeLimit);

  if (modifiedString != NULL) {
    printf("Modified string: %s\n", modifiedString); // Output: Modified string: This is a test /
    free(modifiedString); // Free the dynamically allocated memory
  } else {
    printf("String exceeds size limit.\n");
  }

  return 0;
}
