#include <iostream>
#include <fstream>
#include <nlohmann/json.hpp>

using json = nlohmann::json;

// Function to parse JSON configuration file
std::map<std::string, std::string> parseDeviceConfig(const std::string& configFile) {
    std::map<std::string, std::string> deviceSettings;
    try {
        std::ifstream configStream(configFile);
        json config = json::parse(configStream);

        // Extract and validate device parameters
        for (const auto& [key, value] : config.items()) {
            if (key == "deviceId" && value.is_string()) {
                deviceSettings["deviceId"] = value;
            } else if (key == "sensorType" && value.is_string()) {
                deviceSettings["sensorType"] = value;
            } else {
                std::cerr << "Error: Invalid parameter name or type in config file." << std::endl;
                return {}; // Return empty map on error
            }
        }

    } catch (const json::parse_error& e) {
        std::cerr << "Error parsing JSON configuration file: " << e.what() << std::endl;
    }
    return deviceSettings;
}


int main() {
    // Example usage
    std::string configFile = "device_config.json"; 
    auto settings = parseDeviceConfig(configFile);

    if (!settings.empty()) {
        std::cout << "Device ID: " << settings["deviceId"] << std::endl;
        std::cout << "Sensor Type: " << settings["sensorType"] << std::endl;
    }
    return 0;
}
