        while (true) {
            std::string imagePath;
            { 
                std::unique_lock<std::mutex> lock(imageQueueMutex);
                conditionVariable.wait(lock, [&imageQueue] { return !imageQueue.empty(); });
                imagePath = imageQueue.front();
