```javascript
function copyBytes(dataChunks, startByte, numBytes) {
  const newBuffer = Buffer.allocUnsafe(numBytes);
  for (let i = 0; i < dataChunks.length; i++) {
    const chunk = dataChunks[i];
    if (startByte >= chunk.length) continue;
    const bytesToCopy = Math.min(numBytes - (i * chunk.length), chunk.length - startByte);
    chunk.copy(newBuffer, i * chunk.length, startByte, startByte + bytesToCopy);
    startByte += bytesToCopy;
  }
  return newBuffer;
}
``` 


