public class OAuth2TokenProcessor {

    private final TokenValidator validator;
    private final JsonDeserializer deserializer;
    private final ErrorLogger errorLogger;
    private final StatusReporter statusReporter;

    // ... Constructor, dependency injection for validator, deserializer, logger, reporter ...

    public CompletableFuture<OAuth2AccessToken> processToken(byte[] tokenBytes, Class<? extends OAuth2AccessToken> accessTokenClass) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                String json = new String(tokenBytes);
                // ... Deserialize JSON using deserializer ...
                OAuth2AccessToken token = deserializer.deserialize(json, accessTokenClass);

                // ... Validate token using validator ...
                if (validator.isValid(token)) {
                    statusReporter.reportSuccess(token, System.currentTimeMillis());
                    return token;
                } else {
                    errorLogger.logValidationFailure(token, json);
                    statusReporter.reportFailure(token, "Invalid Token", System.currentTimeMillis());
                    return null;
                }
            } catch (IOException | JsonProcessingException e) {
                errorLogger.logSerializationError(e, tokenBytes);
                statusReporter.reportFailure(token, e.getMessage(), System.currentTimeMillis());
                return null;
            }
        });
    }

}
```



