class ResilientDNSClient {
private:
  std::vector<std::unique_ptr<DNSProvider>> providers;
  std::mutex lock;
  std::condition_variable cv;
  std::queue<std::pair<std::string, int>> requests;
  int currentProviderIndex = 0;

public:
  ResilientDNSClient(const std::vector<std::unique_ptr<DNSProvider>>& providers) : providers(providers) {}

  void processRequests() {
    while (true) {
      std::lock_guard<std::mutex> guard(lock);
      if (!requests.empty()) {
        auto [hostname, protocol] = requests.front();
        requests.pop();
        cv.notify_one();

        try {
          std::string ipAddress = providers[currentProviderIndex]->resolve(hostname, protocol);
          // Handle success and return IP address
        } catch (const std::exception& e) {
          std::cerr << "Error resolving hostname: " << e.what() << std::endl;
          currentProviderIndex = (currentProviderIndex + 1) % providers.size(); // Cycle to next provider
        }
      }
    }
  }

  void addRequest(const std::string& hostname, int protocol) {
    std::lock_guard<std::mutex> guard(lock);
    requests.push({hostname, protocol});
    cv.notify_one(); // Notify waiting thread to process request
  }
};



