#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct NetworkEvent {
    int eventId;
    time_t timestamp;
    enum EventType eventType;
    struct NetworkEvent *next;
} NetworkEvent;

typedef struct EventHandler {
    NetworkEvent *head;
    pthread_mutex_t lock;
    void (*logCallback)(const char *, int);
} EventHandler;

EventHandler *eventHandlerCreate() {
    EventHandler *handler = malloc(sizeof(EventHandler));
    if (!handler) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    handler->head = NULL;
    pthread_mutex_init(&handler->lock, NULL);
    return handler;
}

void eventHandlerDestroy(EventHandler *handler) {
    NetworkEvent *current = handler->head, *next;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&handler->lock);
    free(handler);
}

void eventHandlerEnqueue(EventHandler *handler, int eventId, time_t timestamp, enum EventType eventType) {
    NetworkEvent *newEvent = malloc(sizeof(NetworkEvent));
    if (!newEvent) {
        handler->logCallback("Memory allocation failed", 1);
        return;
    }
    newEvent->eventId = eventId;
    newEvent->timestamp = timestamp;
    newEvent->eventType = eventType;
    newEvent->next = handler->head;
    pthread_mutex_lock(&handler->lock);
    handler->head = newEvent;
    pthread_mutex_unlock(&handler->lock);
}

// ... other functions for event processing, logging, etc. 


```




