        eventQueue.push(event);
        cv.notify_one();
    }

    void run() {
        while (true) {
            std::unique_lock<std::mutex> lock(dataMutex);
            cv.wait(lock, [this] { return !eventQueue.empty(); });
            const std::string& event = eventQueue.front();
            eventQueue.pop();
            lock.unlock();

