void insertStringAfter(std::forward_list<std::string>& lst, const std::string& find, const std::string& insert) {
  auto it = lst.before_begin();
  for (auto pos = lst.begin(); pos != lst.end(); ++pos) {
    if (*pos == find) {
      it = pos;
      break;
    }
  }
  lst.insert(it, insert);
}
