function copyBytes(dataChunks, startByte, endByte) {
  if (startByte < 0 || endByte > dataChunks.length || startByte > endByte) {
    throw new Error('Invalid byte range.');
  }

  let copiedData = Buffer.alloc(endByte - startByte);
  let offset = 0;
  for (let i = startByte; i <= endByte; i++) {
    copiedData[offset] = dataChunks[i];
    offset++;
  }
  return copiedData;
}
