    public BattleStrategy getBattleStrategy(@PathVariable String pokemonName) {
        String cachedData = cache.get(pokemonName); 
        if (cachedData != null) {
            return fromCache(cachedData); // Deserialize cached strategy
        }

        PokemonType type = typeRepository.findByPokemonName(pokemonName).orElseThrow(() -> new NotFoundException("Pokemon not found"));

