// Thread for processing indications from the message queue
void *process_indications(void *arg) {
    while (1) {
        // Acquire lock to protect shared resources
        pthread_mutex_lock(&queue_lock);

        // Check if there are indications in the queue
        if (queue.head != queue.tail) {
            PHYIndication indication = queue.buffer[queue.tail]; 
            queue.tail = (queue.tail + 1) % queue.capacity; // Advance tail pointer

            // Process the indication (e.g., store in database, trigger alerts)
            printf("Processing indication: cell_id=%d, rssi=%d\n", indication.cell_id, indication.rssi); 
        }

        pthread_mutex_unlock(&queue_lock);

        // Sleep for a short duration to avoid busy waiting
        usleep(1000); // Adjust as needed
    }
    return NULL;
}



