        }
    }

    private DataObject DeserializeData(byte[] data) 
    {
        BinaryFormatter formatter = new BinaryFormatter();
        using (MemoryStream stream = new MemoryStream(data))
        {
            return (DataObject)formatter.Deserialize(stream);
        }
    }

    public void SerializeAndWriteData(DataObject data, string outputPath)
    {
        try
        {
            BinaryFormatter formatter = new BinaryFormatter();
            using (FileStream stream = File.Create(outputPath))
            {
                formatter.Serialize(stream, data);
            }

            Console.WriteLine($"Data written to {outputPath}");
        }
        catch (Exception ex)
        {
            // Implement error handling and logging
        }
    }
}


