    uint16_t rx_ue_information_tag;
    bool crcflag;
} PduData;

pthread_mutex_t pdu_data_lock = PTHREAD_MUTEX_INITIALIZER; 
static PduData *pdu_data_pool = NULL;
static size_t pdu_data_size = 0;

void initialize_pdu_data_pool(size_t size) {
    pdu_data_size = size;
    pdu_data_pool = malloc(sizeof(PduData) * size); 
}

void free_pdu_data_pool() {
    free(pdu_data_pool);
}

NFAPI_CRC_INDICATION_PDU_T* generate_crc_indications(size_t count) {
    if (count > pdu_data_size) {
        fprintf(stderr, "Error: Requested PDU count exceeds the allocated pool size.\n");
        return NULL;
    }

    pthread_mutex_lock(&pdu_data_lock); 

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * count); 

    for (size_t i = 0; i < count; ++i) {
        // Populate PDUs with random data
        pdus[i].rnti = pdu_data_pool[i].rnrti; // Assuming some logic to assign RNTI from the pool
        pdus[i].rx_ue_information_tag = pdu_data_pool[i].rx_ue_information_tag; 
        pdus[i].crcflag = pdu_data_pool[i].crcflag;
        // ... Add other fields as needed
    }

    pthread_mutex_unlock(&pdu_data_lock);

    return pdus;
}


