  if path == '/users':
    return 'User Service'
  elif path == '/products':
    return 'Product Service'
  else:
    return 'Default Service'

# Placeholder for service discovery and health checks
service_registry = {
  'User Service': {'status': 'UP', 'region': 'us-east-1'},
  'Product Service': {'status': 'DOWN', 'region': 'us-west-2'} 
}

@app.route('/api/<path:path>', methods=['GET', 'POST'])
def handle_request(path):
    service_name = route_request(path)

    if service_name in service_registry and service_registry[service_name]['status'] == 'UP':
        # Forward request to the appropriate backend service 
        return jsonify({'message': f'Request routed to {service_name} in {service_registry[service_name]["region"]} region'})  
    else:
        return jsonify({'error': 'Service unavailable'}), 503

if __name__ == '__main__':
  app.run(debug=True)   
```


