#include <thread> 
#include <mutex> 
#include <condition_variable>
#include <queue>

class FinancialDataProcessor {
public:
  FinancialDataProcessor() : stopFlag(false) {}

  void processQuotes(const std::vector<Quote>& quotes) {
    std::lock_guard<std::mutex> lock(dataMutex);
    quoteQueue.push(quotes);
    conditionVariable.notify_one();
  }

  void start() {
    processingThread = std::thread([this]() { 
      while (!stopFlag) {
        std::unique_lock<std::mutex> lock(dataMutex);
        conditionVariable.wait(lock, [this] { return !quoteQueue.empty(); });

        std::vector<Quote> processedQuotes = quoteQueue.front();
