        // SparkSession Configuration
        SparkSession spark = SparkSession
                .builder()
                .appName("DynamicDataPipeline")
                .getOrCreate();

        // Data Processing Logic (Using Spark Streaming)
        val df = spark.readStream
                .format("kafka")
