['```cpp
//  Header file for core framework components 

#include <memory>
#include <thread>
#include <condition_variable>
#include <mutex>

class DataConsumer {
public:
    virtual void processData(const std::string& data) = 0;
};

class StreamProcessor {
private:
    std::queue<std::string> dataBuffer;
    std::mutex bufferMutex;
    std::condition_variable dataAvailable;
    std::vector<std::unique_ptr<DataConsumer>> consumers;

public:
    StreamProcessor(int consumerCount) : consumers(consumerCount) { }

    void addConsumer(std::unique_ptr<DataConsumer> consumer) {
        consumers.push_back(std::move(consumer));
    }

    void pushData(const std::string& data) {
        {
            std::lock_guard<std::mutex> lock(bufferMutex);
            dataBuffer.push(data);
        }
        dataAvailable.notify_one();
    }

    void process() {
        std::thread consumerThread([this](){
            while (true) {
                std::string data;
                {
                    std::unique_lock<std::mutex> lock(bufferMutex);
                    dataAvailable.wait(lock, [this]{ return !dataBuffer.empty(); });
                    data = dataBuffer.front();
                    dataBuffer.pop();
                }

                for (auto& consumer : consumers) {
                    consumer->processData(data);
                }
            }
        });
    }
};



//  Implementation of DataConsumer classes for specific use cases 
// ...




