class NfapiProcessor {
 public:
  NfapiProcessor(int max_threads = 4) : max_threads_(max_threads) {}

  void process_pdu(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
    {
      std::lock_guard<std::mutex> lock(queue_mutex_);
      pdu_queue_.push(pdu);
    }
    cv_.notify_one(); 
  }

  void start() {
    for (int i = 0; i < max_threads_; ++i) {
      threads_.emplace_back([this]() { process_loop(); });
    }
  }

 private:
  void process_loop() {
    while (true) {
      std::unique_lock<std::mutex> lock(queue_mutex_);
      cv_.wait(lock, [this]{ return !pdu_queue_.empty(); });

      const NFAPI_CRC_INDICATION_PDU_T& pdu = pdu_queue_.front();
      pdu_queue_.pop();
      lock.unlock();

