// DynamicConnectionPool class 

public class DynamicConnectionPool {
    private final String dataSourceName; // Name of the data source (e.g., "primaryDB")
    private final int initialPoolSize; // Starting number of connections
    private final int maxPoolSize; // Maximum allowed connection count
    private final ConnectionFactory connectionFactory; 

    private ConcurrentMap<String, PoolStats> poolStatistics = new ConcurrentHashMap<>(); 

    // Constructor with parameters
    public DynamicConnectionPool(String dataSourceName, int initialPoolSize, int maxPoolSize, ConnectionFactory connectionFactory) {
        this.dataSourceName = dataSourceName;
        this.initialPoolSize = initialPoolSize;
        this.maxPoolSize = maxPoolSize;
        this.connectionFactory = connectionFactory;

        // Initialize pool with initial connections
    }

    public synchronized Connection getConnection() throws SQLException {
        PoolStats stats = poolStatistics.computeIfAbsent(dataSourceName, k -> new PoolStats());
        if (stats.availableConnections < initialPoolSize) {
            stats.availableConnections++; 
            return connectionFactory.createConnection();
        } else {
            // Handle pool exhaustion - consider metrics and retry logic here
        }
    }

    public synchronized void releaseConnection(Connection connection) throws SQLException {
        connection.close(); 
    }


    private class PoolStats {
        int availableConnections = 0; // Number of currently available connections
        // Add more metrics like recentQueryTimes, responseRates, etc. here... 

    } 



