int load_resource_bundle(const char* file_path, int* bundle_size) {
  FILE *fp = fopen(file_path, "rb");
  if (fp == NULL) {
    perror("Error opening resource file");
    return -1;
  }

  fseek(fp, 0L, SEEK_END);
  long file_size = ftell(fp);
  rewind(fp);

  *bundle_size = (int)file_size / sizeof(struct ResourceItem); // Assuming struct ResourceItem is defined elsewhere

  // Allocate memory for the bundle and its items dynamically using malloc()
  ResourceBundle* bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle)); 
  if (bundle == NULL) {
    perror("Error allocating memory for resource bundle");
    fclose(fp);
    return -1;
  }

  bundle->items = (struct ResourceItem*) malloc(*bundle_size * sizeof(struct ResourceItem));
  if (bundle->items == NULL) {
    perror("Error allocating memory for resource items");
    free(bundle);
    fclose(fp);
    return -1;
  }

  fread(bundle->items, sizeof(struct ResourceItem), *bundle_size, fp);

  fclose(fp);

  return 0;
}
```



**Explanation:**


* **Resource Bundle Loading:** The `load_resource_bundle` function demonstrates basic C code for loading a resource bundle from a file. It utilizes standard library functions like `fopen`, `fseek`, `ftell`, `rewind`, `fread`, and `malloc` to handle file operations, memory allocation, and data reading. 
