        ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_THREADS);

        try (CloseableHttpClient httpClient = HttpClients.createDefault()) {
            // Implement API call logic with rate limiting and authentication
            for (int i = 0; i < 10; i++) { // Fetch 10 batches of data
                executor.execute(new DataFetcherTask(httpClient, i * BATCH_SIZE));
            }
        } catch (Exception e) {
            logger.error("Error during processing:", e);
        } finally {
            executor.shutdown();
            // Log final statistics and process results 
        }
    }

    private static class DataFetcherTask implements Runnable {
        private final CloseableHttpClient httpClient;
        private final int startIndex;

        public DataFetcherTask(CloseableHttpClient httpClient, int startIndex) {
            this.httpClient = httpClient;
            this.startIndex = startIndex;
        }

        @Override
        public void run() {
            try {
                // Fetch data from API and process it
                List<Integer> data = fetchData(httpClient, startIndex);
                processPairs(data);
            } catch (Exception e) {
                logger.error("Error processing batch " + startIndex, e);
            }
        }

    }

}

