// Global Redis client instance
var redisClient *redis.Client

func init() {
	// Connect to Redis
	redisAddr := os.Getenv("REDIS_ADDR") 
	if redisAddr == "" {
		log.Fatal("REDIS_ADDR environment variable not set")
	}
	redisClient = redis.NewClient(&redis.Options{
		Addr:     redisAddr,
		Password: "", // Set Redis password if required
		DB:       0,  // Use default DB
	})
	_, err := redisClient.Ping(context.Background()).Result()
	if err != nil {
		log.Fatalf("Failed to connect to Redis: %v", err)
	}

}


// User struct representing authenticated user data
type User struct {
	ID        int    `json:"id"`
	Username  string `json:"username"`
	Token     string `json:"token"`
	Role      string `json:"role"`
	ExpiryAt time.Time `json:"expiry_at"`
}


// Example API endpoint demonstrating authentication and caching
func handleUserRequest(w http.ResponseWriter, r *http.Request) {
	username := r.URL.Query().Get("username")

	// Retrieve user data from cache using username as key
	cachedUser, err := redisClient.Get(context.Background(), fmt.Sprintf("user:%s", username)).Result()
	if err != nil {
		log.Printf("Error retrieving user from cache: %v", err)
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}

	// If user found in cache, return cached data
	if cachedUser != "" {
		var user User
		err := json.Unmarshal([]byte(cachedUser), &user)
		if err != nil {
			log.Printf("Error unmarshalling user from cache: %v", err)
			http.Error(w, "Internal Server Error", http.StatusInternalServerError)
			return
		}

		// Validate token expiry
		if time.Now().After(user.ExpiryAt) {
			log.Printf("Token expired for user %s", username)
			// Handle token expiry - prompt user to refresh
			http.Error(w, "Authentication required. Please refresh your token.", http.StatusUnauthorized)
			return 
		}

		fmt.Fprintf(w, "User: %+v", user)
		return
	}

	// If not in cache, authenticate with OAuth2 service
	// ...

	// Store validated user data in redis cache (with expiry)
	// ...


}




func main() {
	http.HandleFunc("/user", handleUserRequest)
	log.Fatal(http.ListenAndServe(":8080", nil)) 
}

```



