// Java Microservice for Log Ingestion 

import io.netty.channel.ChannelFuture;
import io.netty.channel.ChannelHandlerContext;
import io.netty.channel.SimpleChannelInboundHandler;
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerConfig;
import org.apache.kafka.clients.producer.ProducerRecord;

import java.util.Properties;

public class LogIngestor extends SimpleChannelInboundHandler<String> {

    private final KafkaProducer<String, String> kafkaProducer;

    public LogIngestor() {
        Properties props = new Properties();
        props.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092"); // Kafka broker address
        props.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, "org.apache.kafka.common.serialization.StringSerializer");
        props.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, "org.apache.kafka.common.serialization.StringSerializer");

        kafkaProducer = new KafkaProducer<>(props);
    }

    @Override
    protected void channelRead0(ChannelHandlerContext ctx, String logMessage) throws Exception {
        // Process and send the log message to Kafka
        kafkaProducer.send(new ProducerRecord<>("log_topic", logMessage)); 
    }

    @Override
    public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) throws Exception {
        // Handle exceptions gracefully
        cause.printStackTrace();
        ctx.close();
    }

}



