use serde::{Deserialize, Serialize};
use futures::StreamExt;
use kafka::consumer::{Consumer, Stream};
use tokio::runtime::Runtime;


#[derive(Debug, Deserialize, Serialize)]
struct LogEntry {
    timestamp: u64,
    message: String,
}

async fn process_logs(consumer: Consumer<LogEntry>) {
    let mut stream = consumer.stream();
    while let Some(result) = stream.next().await {
        match result {
            Ok(record) => {
                println!("Processing log entry: {:?}", record); 
                // Perform analysis, alerting, and other processing here
            }
            Err(e) => {
                println!("Error consuming message: {}", e);
            }
        }
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let consumer = KafkaConsumerBuilder::new("log_topic") // Replace with your topic name
        .build()
        .await?;
    Runtime::new().unwrap().block_on(process_logs(consumer));
    Ok(())
}

