// Gateway service to handle incoming requests and route them to appropriate microservices.
import io.netty.handler.codec.http.*;

public class UserActivityLogGateway {

    private final UserService userService;
    private final ActivityLogService activityLogService;
    private final EventBroker eventBroker;

    public UserActivityLogGateway(UserService userService, ActivityLogService activityLogService, EventBroker eventBroker) {
        this.userService = userService;
        this.activityLogService = activityLogService;
        this.eventBroker = eventBroker;
    }

    // Handle incoming HTTP requests and route them based on API endpoints.
    @Override
    public void serveRequest(HttpRequest request, HttpResponse response) {

        String path = request.uri(); 

        if (path.startsWith("/user")) {
            userService.handleRequest(request, response);
        } else if (path.startsWith("/activity")) {
            activityLogService.handleRequest(request, response);
        } else {
            // Handle unhandled requests with appropriate error responses.
            response.setStatus(HttpResponseStatus.NOT_FOUND);
        }
    }

}



