        printf("Name: %s\n", sqlite3_column_text(stmt, 0));
        printf("City: %s\n", sqlite3_column_text(stmt, 1));
        printf("Address: %s\n", sqlite3_column_text(stmt, 2));
    } else {
        fprintf(stderr, "SQL error: %s\n", sqlite3_errmsg(db));
    }

    sqlite3_finalize(stmt);
    sqlite3_close(db);
    return 0;
}



